+    pub(crate) fn observe_fixture(&self, timeout: Duration) -> bool {
+        let fixture = self.fixture.as_ref().unwrap();
+        fixture.time.wait_quiet(timeout)
+            && self.drive_fixture(timeout, || fixture.time.now_us(), true)
